<?php require __DIR__.'/../config/bootstrap.php';admin_required();header('Content-Type:text/csv');header('Content-Disposition:attachment;filename=leads-'.date('Y-m-d').'.csv');$o=fopen('php://output','w');fputcsv($o,['ID','Name','Email','Phone','Renovation Interest','Consent','Created']);foreach($pdo->query('SELECT id,name,email,phone,renovation_interest,consent,created_at FROM leads ORDER BY id DESC') as $r)fputcsv($o,$r);fclose($o);